    76  static int tcos_match_card(sc_card_t *card)
    77  {
    78          int i;
    79
    80          i = _sc_match_atr(card, tcos_atrs, &card->type);
    81          if (i < 0)
    82                  return 0;
    83          return 1;
    84  }
