    87  static int tcos_init(sc_card_t *card)
    88  {
    89          unsigned long flags;
    90
    91          tcos_data *data = malloc(sizeof(tcos_data));
    92          if (!data) return SC_ERROR_OUT_OF_MEMORY;
    93
    94          card->name = "TCOS";
    95          card->drv_data = (void *)data;
    96          card->cla = 0x00;
    97
    98          flags = SC_ALGORITHM_RSA_RAW;
    99          flags |= SC_ALGORITHM_RSA_PAD_PKCS1;
   100          flags |= SC_ALGORITHM_RSA_HASH_NONE;
   101
   102          _sc_card_add_rsa_alg(card, 512, flags, 0);
   103          _sc_card_add_rsa_alg(card, 768, flags, 0);
   104          _sc_card_add_rsa_alg(card, 1024, flags, 0);
   105
   106          if (card->type == SC_CARD_TYPE_TCOS_V3) {
   107                  card->caps |= SC_CARD_CAP_APDU_EXT;
   108                  _sc_card_add_rsa_alg(card, 1280, flags, 0);
   109                  _sc_card_add_rsa_alg(card, 1536, flags, 0);
   110                  _sc_card_add_rsa_alg(card, 1792, flags, 0);
   111                  _sc_card_add_rsa_alg(card, 2048, flags, 0);
   112          }
   113
   114          return 0;
   115  }
